SubProceso ContarMayores(datos[] Como Entero Por Referencia, tamano Como Entero, limite Como Entero) Como Entero
    Definir i Como Entero;
    Definir contador Como Entero;
    contador <- 0;
    Para i <- 0 Hasta tamano - 1 Hacer
        Si datos[i] > limite Entonces
            contador <- contador + 1;
        FinSi
    FinPara
    Retornar contador;
FinSubProceso

Proceso EjecutarConteo
    Dimension vector[5] Como Entero;
    Definir i Como Entero;
    Definir limite Como Entero;
    Para i <- 0 Hasta 4 Hacer
        Leer vector[i];
    FinPara
    Leer limite;
    Escribir ContarMayores(vector, 5, limite);
FinProceso
